#!/usr/bin/env node
import { Server } from "@modelcontextprotocol/server";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";

const server = new Server(
  {
    name: "mock-stdio-server",
    version: "1.0.0",
  },
  {
    capabilities: {
      tools: {},
      resources: {},
      prompts: {},
    },
  }
);

server.setRequestHandler("tools/list", async () => {
  return {
    tools: [
      {
        name: "echo_stdio",
        description: "Echoes message back from stdio process",
        inputSchema: {
          type: "object",
          properties: {
            message: { type: "string" },
          },
          required: ["message"],
        },
      },
      {
        name: "calculate_sum",
        description: "Calculates sum of two numbers",
        inputSchema: {
          type: "object",
          properties: {
            a: { type: "number" },
            b: { type: "number" },
          },
          required: ["a", "b"],
        },
      },
      {
        name: "generate_large_output",
        description: "Generates large text payload to test SpillStore",
        inputSchema: {
          type: "object",
          properties: {
            lines: { type: "integer" },
          },
        },
      },
    ],
  };
});

server.setRequestHandler("tools/call", async (request) => {
  const { name, arguments: args = {} } = request.params;

  if (name === "echo_stdio") {
    return {
      content: [
        {
          type: "text",
          text: `Stdio Echo: ${args.message}`,
        },
      ],
    };
  }

  if (name === "calculate_sum") {
    const sum = Number(args.a) + Number(args.b);
    return {
      content: [
        {
          type: "text",
          text: `Result: ${sum}`,
        },
      ],
    };
  }

  if (name === "generate_large_output") {
    const linesCount = Number(args.lines) || 2000;
    const lines = [];
    for (let i = 1; i <= linesCount; i++) {
      lines.push(`Line ${i}: This is a sample large payload stream generated by stdio MCP test server.`);
    }
    return {
      content: [
        {
          type: "text",
          text: lines.join("\n"),
        },
      ],
    };
  }

  throw new Error(`Unknown tool: ${name}`);
});

server.setRequestHandler("resources/list", async () => {
  return {
    resources: [
      {
        uri: "stdio://test/sample-doc",
        name: "Sample Stdio Document",
        mimeType: "text/plain",
        description: "A test document resource hosted on stdio server",
      },
    ],
  };
});

server.setRequestHandler("resources/read", async (request) => {
  const { uri } = request.params;
  if (uri === "stdio://test/sample-doc") {
    return {
      contents: [
        {
          uri,
          mimeType: "text/plain",
          text: "Hello from stdio MCP resource content!",
        },
      ],
    };
  }
  throw new Error(`Resource not found: ${uri}`);
});

server.setRequestHandler("prompts/list", async () => {
  return {
    prompts: [
      {
        name: "test_prompt",
        description: "A sample prompt template",
        arguments: [{ name: "topic", description: "Prompt topic", required: true }],
      },
    ],
  };
});

server.setRequestHandler("prompts/get", async (request) => {
  const { name, arguments: args = {} } = request.params;
  return {
    messages: [
      {
        role: "user",
        content: {
          type: "text",
          text: `Please give me a tutorial on ${args.topic || "general computing"}`,
        },
      },
    ],
  };
});

const transport = new StdioServerTransport();
await server.connect(transport);
